INSERT INTO schools (id, slug, code, name, short_name, type, region_code, city, founded, students, highlight, website, description, scholarships, hidden, is_custom) VALUES
  ('hust', 'dai-hoc-bach-khoa-ha-noi', 'BKA', 'Đại học Bách khoa Hà Nội', 'ĐH Bách khoa Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1956, 35000, 'Top 5 Việt Nam', 'https://hust.edu.vn', 'Trường đại học kỹ thuật đa ngành hàng đầu, mạnh về công nghệ thông tin, điện – điện tử, cơ khí và khoa học máy tính.', 'Học bổng khuyến khích học tập mỗi học kỳ cho 10% sinh viên, học bổng tài năng cho thủ khoa đầu vào.', false, false),
  ('neu', 'dai-hoc-kinh-te-quoc-dan', 'KHA', 'Đại học Kinh tế Quốc dân', 'ĐH Kinh tế Quốc dân', 'cong-lap', 'bac', 'Hà Nội', 1956, 30000, 'Top 3 khối kinh tế', 'https://neu.edu.vn', 'Trường trọng điểm về kinh tế, quản lý và quản trị kinh doanh với nhiều chương trình tiên tiến giảng dạy bằng tiếng Anh.', 'Học bổng khuyến khích, học bổng doanh nghiệp và học bổng Tài năng NEU.', false, false),
  ('ftu', 'truong-dai-hoc-ngoai-thuong', 'NTH', 'Trường Đại học Ngoại thương', 'ĐH Ngoại thương', 'cong-lap', 'bac', 'Hà Nội', 1960, 18000, 'Top 1 khối kinh tế đối ngoại', 'https://ftu.edu.vn', 'Đào tạo kinh tế đối ngoại, kinh doanh quốc tế, tài chính và luật thương mại quốc tế.', 'Học bổng khuyến khích học tập, học bổng từ hơn 50 đối tác doanh nghiệp.', false, false),
  ('uet', 'truong-dai-hoc-cong-nghe-dhqghn', 'QHI', 'Trường Đại học Công nghệ – ĐHQGHN', 'ĐH Công nghệ – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 2004, 9000, 'Top 3 ngành CNTT', 'https://uet.vnu.edu.vn', 'Trường thành viên ĐHQG Hà Nội, định hướng nghiên cứu về công nghệ thông tin, điện tử viễn thông và trí tuệ nhân tạo.', 'Học bổng ĐHQGHN, học bổng doanh nghiệp công nghệ (Samsung, Viettel, FPT…).', false, false),
  ('hmu', 'truong-dai-hoc-y-ha-noi', 'YHB', 'Trường Đại học Y Hà Nội', 'ĐH Y Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1902, 12000, 'Trường y lâu đời nhất', 'https://hmu.edu.vn', 'Trường y khoa hàng đầu, đào tạo bác sĩ đa khoa, y học cổ truyền, răng hàm mặt và các ngành sức khỏe.', 'Học bổng khuyến khích học tập và học bổng tài trợ từ các bệnh viện đối tác.', false, false),
  ('hup', 'truong-dai-hoc-duoc-ha-noi', 'DKH', 'Trường Đại học Dược Hà Nội', 'ĐH Dược Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1961, 5000, 'Trường dược trọng điểm', 'https://hup.edu.vn', 'Đào tạo dược sĩ và nghiên cứu về dược học, hóa dược, công nghiệp dược.', 'Học bổng khuyến khích học tập, học bổng doanh nghiệp dược.', false, false),
  ('ussh', 'truong-dai-hoc-khxhnv-dhqghn', 'QHX', 'Trường ĐH Khoa học Xã hội và Nhân văn – ĐHQGHN', 'ĐH KHXH&NV – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 1995, 13000, 'Top khối xã hội nhân văn', 'https://ussh.vnu.edu.vn', 'Đào tạo báo chí, truyền thông, quan hệ công chúng, tâm lý học và các ngành khoa học xã hội.', 'Học bổng ĐHQGHN, học bổng khuyến khích học tập.', false, false),
  ('hnue', 'truong-dai-hoc-su-pham-ha-noi', 'SPH', 'Trường Đại học Sư phạm Hà Nội', 'ĐH Sư phạm Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1951, 20000, 'Trường sư phạm trọng điểm', 'https://hnue.edu.vn', 'Trường sư phạm trọng điểm quốc gia, đào tạo giáo viên và cử nhân khoa học giáo dục.', 'Sinh viên sư phạm được hỗ trợ học phí và sinh hoạt phí theo quy định nhà nước.', false, false),
  ('vnua', 'hoc-vien-nong-nghiep-viet-nam', 'HVN', 'Học viện Nông nghiệp Việt Nam', 'HV Nông nghiệp VN', 'cong-lap', 'bac', 'Hà Nội', 1956, 30000, 'Trọng điểm nông nghiệp', 'https://vnua.edu.vn', 'Đào tạo nông nghiệp, công nghệ thực phẩm, môi trường và kinh tế nông nghiệp.', 'Nhiều học bổng doanh nghiệp, hỗ trợ ký túc xá cho tân sinh viên.', false, false),
  ('fpt', 'truong-dai-hoc-fpt', 'FPT', 'Trường Đại học FPT', 'ĐH FPT', 'tu-thuc', 'bac', 'Hà Nội, TP.HCM, Đà Nẵng, Cần Thơ, Quy Nhơn', 2006, 40000, 'Học kỳ doanh nghiệp', 'https://daihoc.fpt.edu.vn', 'Đại học tư thục định hướng ứng dụng, mạnh về phần mềm, AI và thiết kế; có học kỳ thực tập tại doanh nghiệp.', 'Học bổng toàn phần và bán phần theo kết quả thi đánh giá năng lực của trường.', false, false),
  ('dut', 'truong-dai-hoc-bach-khoa-dh-da-nang', 'DDK', 'Trường Đại học Bách khoa – ĐH Đà Nẵng', 'ĐH Bách khoa Đà Nẵng', 'cong-lap', 'trung', 'Đà Nẵng', 1975, 14000, 'Trọng điểm kỹ thuật miền Trung', 'https://dut.udn.vn', 'Trường kỹ thuật trọng điểm miền Trung, đào tạo CNTT, điện, cơ khí, xây dựng và kiến trúc.', 'Học bổng khuyến khích học tập, học bổng doanh nghiệp FDI tại Đà Nẵng.', false, false),
  ('rmit', 'dai-hoc-rmit-viet-nam', 'RMU', 'Đại học RMIT Việt Nam', 'ĐH RMIT Việt Nam', 'quoc-te', 'nam', 'TP. Hồ Chí Minh, Hà Nội', 2001, 9000, 'Bằng cấp quốc tế (Úc)', 'https://rmit.edu.vn', 'Đại học quốc tế, giảng dạy hoàn toàn bằng tiếng Anh; xét tuyển bằng học bạ và chứng chỉ tiếng Anh.', 'Học bổng Tài năng, học bổng Nữ sinh STEM, học bổng theo hoàn cảnh.', false, false),
  ('ueh', 'dai-hoc-kinh-te-tphcm', 'KSA', 'Đại học Kinh tế TP. Hồ Chí Minh', 'ĐH Kinh tế TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1976, 32000, 'Top khối kinh tế phía Nam', 'https://ueh.edu.vn', 'Đại học đa ngành về kinh tế, kinh doanh, công nghệ và thiết kế, nhiều chương trình cử nhân tài năng.', 'Học bổng Tiếp sức, học bổng khuyến khích và học bổng doanh nghiệp.', false, false),
  ('hcmus', 'truong-dai-hoc-khtn-dhqg-hcm', 'QST', 'Trường ĐH Khoa học Tự nhiên – ĐHQG-HCM', 'ĐH KHTN TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1996, 20000, 'Mạnh về khoa học máy tính', 'https://hcmus.edu.vn', 'Đào tạo khoa học cơ bản và công nghệ: khoa học máy tính, CNTT, môi trường, sinh học.', 'Học bổng khuyến khích, học bổng chương trình tài năng.', false, false),
  ('tdtu', 'truong-dai-hoc-ton-duc-thang', 'DTT', 'Trường Đại học Tôn Đức Thắng', 'ĐH Tôn Đức Thắng', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1997, 25000, 'Tự chủ tài chính', 'https://tdtu.edu.vn', 'Trường công lập tự chủ, đào tạo đa ngành: luật, thiết kế, môi trường, kỹ thuật.', 'Học bổng thủ khoa, học bổng khuyến khích học tập hằng học kỳ.', false, false),
  ('ctu', 'truong-dai-hoc-can-tho', 'TCT', 'Trường Đại học Cần Thơ', 'ĐH Cần Thơ', 'cong-lap', 'nam', 'Cần Thơ', 1966, 40000, 'Trọng điểm ĐBSCL', 'https://ctu.edu.vn', 'Trường đại học trọng điểm vùng Đồng bằng sông Cửu Long, đa ngành, mạnh về nông nghiệp và sư phạm.', 'Học bổng khuyến khích, học bổng vùng khó khăn, hỗ trợ ký túc xá.', false, false);
