INSERT INTO majors (id, slug, code, name, group_id, summary, description, demand, growth, hidden, is_custom) VALUES
  ('cong-nghe-thong-tin', 'cong-nghe-thong-tin', '7480201', 'Công nghệ thông tin', 'cntt', 'Thiết kế, xây dựng và vận hành hệ thống phần mềm, mạng và dữ liệu cho doanh nghiệp.', 'Ngành Công nghệ thông tin trang bị nền tảng lập trình, cơ sở dữ liệu, mạng máy tính và kỹ năng phát triển sản phẩm số. Sinh viên được thực hành qua dự án thật từ năm 2–3.', 'Rất cao', 15, false, false),
  ('khoa-hoc-may-tinh', 'khoa-hoc-may-tinh', '7480101', 'Khoa học máy tính', 'cntt', 'Nền tảng toán – thuật toán cho phần mềm, trí tuệ nhân tạo và hệ thống thông minh.', 'Tập trung vào lý thuyết tính toán, thuật toán, học máy và hệ thống. Phù hợp với bạn thích toán và muốn làm nghiên cứu hoặc sản phẩm công nghệ lõi.', 'Rất cao', 17, false, false),
  ('ky-thuat-phan-mem', 'ky-thuat-phan-mem', '7480103', 'Kỹ thuật phần mềm', 'cntt', 'Quy trình chuyên nghiệp để phát triển, kiểm thử và vận hành phần mềm quy mô lớn.', 'Chú trọng quy trình phát triển phần mềm (Agile, DevOps), kiểm thử và quản lý chất lượng. Nhiều trường có học kỳ thực tập tại doanh nghiệp.', 'Rất cao', 14, false, false),
  ('tri-tue-nhan-tao', 'tri-tue-nhan-tao', '7480107', 'Trí tuệ nhân tạo', 'cntt', 'Xây dựng hệ thống học từ dữ liệu: thị giác máy tính, xử lý ngôn ngữ, AI tạo sinh.', 'Ngành mới, đào tạo chuyên sâu về học máy, học sâu và ứng dụng AI. Yêu cầu nền tảng toán tốt (xác suất, đại số tuyến tính).', 'Rất cao', 22, false, false),
  ('marketing', 'marketing', '7340115', 'Marketing', 'kinh-te', 'Nghiên cứu thị trường, xây dựng thương hiệu và thúc đẩy doanh số trên nền tảng số.', 'Ngành học về chiến lược tiếp thị, nghiên cứu thị trường, xây dựng thương hiệu, tối ưu hoá trải nghiệm khách hàng và thúc đẩy doanh số trên đa nền tảng truyền thông hiện đại.', 'Cao', 18, false, false),
  ('quan-tri-kinh-doanh', 'quan-tri-kinh-doanh', '7340101', 'Quản trị kinh doanh', 'kinh-te', 'Điều hành doanh nghiệp: chiến lược, nhân sự, vận hành và tài chính.', 'Trang bị kiến thức quản trị tổng hợp để điều hành doanh nghiệp, khởi nghiệp hoặc làm quản lý ở các phòng ban.', 'Cao', 10, false, false),
  ('kinh-doanh-quoc-te', 'kinh-doanh-quoc-te', '7340120', 'Kinh doanh quốc tế', 'kinh-te', 'Xuất nhập khẩu, logistics và đàm phán thương mại với đối tác nước ngoài.', 'Đào tạo nghiệp vụ thương mại quốc tế, logistics, thanh toán quốc tế và đàm phán. Yêu cầu tiếng Anh tốt.', 'Cao', 12, false, false),
  ('tai-chinh-ngan-hang', 'tai-chinh-ngan-hang', '7340201', 'Tài chính – Ngân hàng', 'kinh-te', 'Quản lý dòng tiền, đầu tư, tín dụng và nghiệp vụ ngân hàng.', 'Học về thị trường tài chính, ngân hàng thương mại, đầu tư và quản trị rủi ro; nhiều cơ hội tại ngân hàng, công ty chứng khoán.', 'Cao', 8, false, false),
  ('ke-toan', 'ke-toan', '7340301', 'Kế toán', 'kinh-te', 'Ghi nhận, phân tích số liệu tài chính và lập báo cáo cho doanh nghiệp.', 'Đào tạo kế toán tài chính, kế toán quản trị, kiểm toán và thuế; có thể hướng tới chứng chỉ ACCA/CPA.', 'Cao', 6, false, false),
  ('quan-tri-du-lich', 'quan-tri-du-lich', '7810103', 'Quản trị dịch vụ du lịch và lữ hành', 'kinh-te', 'Thiết kế tour, vận hành dịch vụ du lịch và trải nghiệm khách hàng.', 'Đào tạo quản trị dịch vụ du lịch, lữ hành, khách sạn và sự kiện; chú trọng ngoại ngữ và kỹ năng giao tiếp.', 'Trung bình', 9, false, false),
  ('y-khoa', 'y-khoa', '7720101', 'Y khoa', 'y-duoc', 'Đào tạo bác sĩ đa khoa: chẩn đoán, điều trị và chăm sóc sức khỏe cộng đồng.', 'Chương trình 6 năm, học lý thuyết y sinh và thực hành lâm sàng tại bệnh viện. Cần sự kiên trì và tinh thần phục vụ.', 'Rất cao', 7, false, false),
  ('duoc-hoc', 'duoc-hoc', '7720201', 'Dược học', 'y-duoc', 'Nghiên cứu, sản xuất, kiểm nghiệm và tư vấn sử dụng thuốc an toàn.', 'Đào tạo dược sĩ đại học 5 năm với kiến thức hoá dược, bào chế, dược lý và quản lý dược.', 'Cao', 8, false, false),
  ('ky-thuat-dien', 'ky-thuat-dien', '7520201', 'Kỹ thuật điện', 'ky-thuat', 'Hệ thống điện, năng lượng tái tạo và tự động hoá công nghiệp.', 'Đào tạo thiết kế, vận hành hệ thống điện, lưới điện thông minh và năng lượng tái tạo.', 'Cao', 10, false, false),
  ('ky-thuat-co-khi', 'ky-thuat-co-khi', '7520103', 'Kỹ thuật cơ khí', 'ky-thuat', 'Thiết kế, chế tạo máy móc và hệ thống sản xuất.', 'Đào tạo thiết kế cơ khí, CAD/CAM, gia công CNC và chế tạo máy cho công nghiệp.', 'Trung bình', 6, false, false),
  ('kien-truc', 'kien-truc', '7580101', 'Kiến trúc', 'nghe-thuat', 'Thiết kế công trình, không gian sống và quy hoạch đô thị.', 'Kết hợp nghệ thuật và kỹ thuật để thiết kế công trình. Xét tuyển khối V (có môn vẽ).', 'Trung bình', 5, false, false),
  ('thiet-ke-do-hoa', 'thiet-ke-do-hoa', '7210403', 'Thiết kế đồ họa', 'nghe-thuat', 'Sáng tạo hình ảnh, nhận diện thương hiệu và sản phẩm truyền thông số.', 'Đào tạo thiết kế nhận diện, ấn phẩm, giao diện số và chuyển động; kết hợp tư duy thẩm mỹ với công cụ số.', 'Cao', 12, false, false),
  ('tam-ly-hoc', 'tam-ly-hoc', '7310401', 'Tâm lý học', 'xa-hoi', 'Hiểu hành vi, cảm xúc con người để tư vấn, trị liệu và phát triển tổ chức.', 'Đào tạo tâm lý học lâm sàng, tâm lý học đường và tâm lý tổ chức; nhu cầu tăng mạnh ở trường học và doanh nghiệp.', 'Cao', 11, false, false),
  ('luat', 'luat', '7380101', 'Luật', 'xa-hoi', 'Nghiên cứu hệ thống pháp luật, tư vấn và bảo vệ quyền lợi hợp pháp.', 'Đào tạo luật dân sự, hình sự, kinh tế và quốc tế; có thể hành nghề luật sư, tư vấn pháp lý doanh nghiệp.', 'Cao', 7, false, false),
  ('quan-he-cong-chung', 'quan-he-cong-chung', '7320108', 'Quan hệ công chúng', 'xa-hoi', 'Xây dựng hình ảnh tổ chức, truyền thông sự kiện và xử lý khủng hoảng.', 'Đào tạo truyền thông chiến lược, quan hệ báo chí, tổ chức sự kiện và truyền thông số.', 'Cao', 13, false, false),
  ('su-pham-toan', 'su-pham-toan', '7140209', 'Sư phạm Toán học', 'giao-duc', 'Đào tạo giáo viên Toán THCS, THPT với phương pháp dạy học hiện đại.', 'Kết hợp kiến thức toán chuyên sâu và nghiệp vụ sư phạm; sinh viên được hỗ trợ học phí, sinh hoạt phí theo quy định.', 'Trung bình', 4, false, false),
  ('cong-nghe-thuc-pham', 'cong-nghe-thuc-pham', '7540101', 'Công nghệ thực phẩm', 'nong-lam', 'Chế biến, bảo quản và kiểm soát chất lượng thực phẩm an toàn.', 'Đào tạo công nghệ chế biến, vi sinh thực phẩm, quản lý chất lượng (HACCP, ISO 22000).', 'Trung bình', 7, false, false),
  ('khoa-hoc-moi-truong', 'khoa-hoc-moi-truong', '7440301', 'Khoa học môi trường', 'nong-lam', 'Đánh giá, xử lý ô nhiễm và phát triển bền vững.', 'Đào tạo quan trắc, đánh giá tác động môi trường, xử lý chất thải và biến đổi khí hậu.', 'Trung bình', 9, false, false);
