  ('tdtu-luat', 'luat-dtt', 'tdtu', 'luat', 'Luật', 'DTT-LU', 'Chính quy', '19 Nguyễn Hữu Thọ, Quận 7, TP.HCM', 26, 30, 4, 200, 'Trung bình', 'Chương trình Luật của Trường Đại học Tôn Đức Thắng đào tạo theo định hướng: nghiên cứu hệ thống pháp luật, tư vấn và bảo vệ quyền lợi hợp pháp. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Tôn Đức Thắng', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('tdtu-thiet-ke-do-hoa', 'thiet-ke-do-hoa-dtt', 'tdtu', 'thiet-ke-do-hoa', 'Thiết kế đồ họa', 'DTT-TK', 'Chính quy', '19 Nguyễn Hữu Thọ, Quận 7, TP.HCM', 28, 32, 4, 120, 'Trung bình', 'Chương trình Thiết kế đồ họa của Trường Đại học Tôn Đức Thắng đào tạo theo định hướng: sáng tạo hình ảnh, nhận diện thương hiệu và sản phẩm truyền thông số. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Tôn Đức Thắng', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('tdtu-khoa-hoc-moi-truong', 'khoa-hoc-moi-truong-dtt', 'tdtu', 'khoa-hoc-moi-truong', 'Khoa học môi trường', 'DTT-MT', 'Chính quy', '19 Nguyễn Hữu Thọ, Quận 7, TP.HCM', 24, 28, 4, 100, 'Cao', 'Chương trình Khoa học môi trường của Trường Đại học Tôn Đức Thắng đào tạo theo định hướng: đánh giá, xử lý ô nhiễm và phát triển bền vững. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Tôn Đức Thắng', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('ctu-cong-nghe-thong-tin', 'cong-nghe-thong-tin-tct', 'ctu', 'cong-nghe-thong-tin', 'Công nghệ thông tin', 'TCT-IT', 'Chính quy', 'Khu II, đường 3/2, Ninh Kiều, Cần Thơ', 18, 22, 4, 400, 'Trung bình', 'Chương trình Công nghệ thông tin của Trường Đại học Cần Thơ đào tạo theo định hướng: thiết kế, xây dựng và vận hành hệ thống phần mềm, mạng và dữ liệu cho doanh nghiệp. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Cần Thơ', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('ctu-cong-nghe-thuc-pham', 'cong-nghe-thuc-pham-tct', 'ctu', 'cong-nghe-thuc-pham', 'Công nghệ thực phẩm', 'TCT-TP', 'Chính quy', 'Khu II, đường 3/2, Ninh Kiều, Cần Thơ', 18, 22, 4, 200, 'Thấp', 'Chương trình Công nghệ thực phẩm của Trường Đại học Cần Thơ đào tạo theo định hướng: chế biến, bảo quản và kiểm soát chất lượng thực phẩm an toàn. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Cần Thơ', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('ctu-su-pham-toan', 'su-pham-toan-tct', 'ctu', 'su-pham-toan', 'Sư phạm Toán học', 'TCT-SPT', 'Chính quy', 'Khu II, đường 3/2, Ninh Kiều, Cần Thơ', 0, 0, 4, 80, 'Cao', 'Chương trình Sư phạm Toán học của Trường Đại học Cần Thơ đào tạo theo định hướng: đào tạo giáo viên Toán THCS, THPT với phương pháp dạy học hiện đại. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Cần Thơ', NULL, NULL, NULL, NULL, NULL, NULL, false, false),
  ('ctu-khoa-hoc-moi-truong', 'khoa-hoc-moi-truong-tct', 'ctu', 'khoa-hoc-moi-truong', 'Khoa học môi trường', 'TCT-MT', 'Chính quy', 'Khu II, đường 3/2, Ninh Kiều, Cần Thơ', 18, 22, 4, 120, 'Thấp', 'Chương trình Khoa học môi trường của Trường Đại học Cần Thơ đào tạo theo định hướng: đánh giá, xử lý ô nhiễm và phát triển bền vững. Sinh viên học lý thuyết nền tảng kết hợp thực hành qua dự án và thực tập tại doanh nghiệp đối tác.', '2026-09', 'Đề án tuyển sinh 2026 – Trường Đại học Cần Thơ', NULL, NULL, NULL, NULL, NULL, NULL, false, false);
