INSERT INTO timeline_events (id, title, start_date, end_date, category, description) VALUES
  ('2027-dgnl-hn-dot-1', 'Thi đánh giá năng lực ĐHQG Hà Nội (HSA) — đợt đầu', '2027-03-13', '2027-03-14', 'dgnl', 'Các đợt thi HSA thường bắt đầu từ tháng 3. Đăng ký trên cổng thi của ĐHQG Hà Nội trước ngày thi vài tuần.'),
  ('2027-dgnl-hcm-dot-1', 'Thi đánh giá năng lực ĐHQG TP.HCM — đợt 1', '2027-04-04', NULL, 'dgnl', 'Kỳ thi thang 1200 điểm, thường tổ chức 2 đợt vào tháng 4 và tháng 5–6.'),
  ('2027-dang-ky-thi-thpt', 'Đăng ký dự thi tốt nghiệp THPT', '2027-04-21', '2027-05-05', 'dang-ky', 'Học sinh lớp 12 đăng ký dự thi qua trường THPT hoặc trực tuyến trên hệ thống của Bộ.'),
  ('2027-thi-thpt', 'Kỳ thi tốt nghiệp THPT', '2027-06-25', '2027-06-26', 'thi', 'Hai ngày thi chính thức. Mang theo giấy báo dự thi và giấy tờ tuỳ thân.'),
  ('2027-cong-bo-diem', 'Công bố điểm thi tốt nghiệp THPT', '2027-07-15', NULL, 'ket-qua', 'Tra cứu điểm thi, sau đó cập nhật điểm vào Trovio để xem lại mức An toàn / Vừa sức / Thử sức.'),
  ('2027-dang-ky-nguyen-vong', 'Đăng ký & điều chỉnh nguyện vọng xét tuyển', '2027-07-16', '2027-07-28', 'dang-ky', 'Đăng ký không giới hạn số nguyện vọng trên hệ thống của Bộ, sắp xếp theo thứ tự ưu tiên. Dùng “Kiểm tra danh sách” ở trang Đã lưu trước khi nộp.'),
  ('2027-nop-le-phi', 'Nộp lệ phí xét tuyển trực tuyến', '2027-07-29', '2027-08-04', 'dang-ky', 'Nộp đúng số lượng nguyện vọng đã đăng ký. Nguyện vọng chưa nộp lệ phí sẽ không được xét.'),
  ('2027-ket-qua-dot-1', 'Công bố kết quả trúng tuyển đợt 1', '2027-08-20', NULL, 'ket-qua', 'Mỗi thí sinh chỉ trúng tuyển 1 nguyện vọng — nguyện vọng có thứ tự ưu tiên cao nhất mà bạn đủ điều kiện.'),
  ('2027-xac-nhan-nhap-hoc', 'Xác nhận nhập học trực tuyến', '2027-08-21', '2027-08-30', 'nhap-hoc', 'Xác nhận nhập học trên hệ thống của Bộ trước hạn, sau đó làm thủ tục theo hướng dẫn của trường.');
